const schemaGraph = ({ route, title, description, type = "Service", faqs = [], article = null, breadcrumbs = [] }) => {
  const graph = [
    { "@type": "Organization", "@id": `${site}/#organization`, name: "MAX SITE", url: `${site}/`, telephone: "+380972692322", sameAs: ["https://t.me/MaxMytt", "https://www.instagram.com/maxlab.ai/"] },
    { "@type": "BreadcrumbList", itemListElement: [{ "@type": "ListItem", position: 1, name: "Головна", item: `${site}/` }, ...breadcrumbs.map((item, index) => ({ "@type": "ListItem", position: index + 2, name: item.name, item: `${site}${item.route}` }))] },
  ];
  if (article) {
    graph.push({ "@type": "Article", headline: title, description, datePublished: updated, dateModified: updated, author: { "@id": `${site}/zasnovnyk/#person` }, publisher: { "@id": `${site}/#organization` }, mainEntityOfPage: `${site}${route}`, image: `${site}/assets/og-max-site.png` });
  } else if (type === "AboutPage") {
    graph.push({ "@type": "AboutPage", name: title, description, url: `${site}${route}`, about: { "@id": `${site}/#organization` } });
    if (route === "/zasnovnyk/") {
      graph.push({ "@type": "Person", "@id": `${site}/zasnovnyk/#person`, name: "Засновник MAX SITE", url: `${site}/zasnovnyk/`, image: `${site}/assets/founder-max-site-v2.jpg`, worksFor: { "@id": `${site}/#organization` }, jobTitle: "Засновник і керівник проєктів MAX SITE" });
    }
  } else {
    graph.push({ "@type": type, name: title, description, url: `${site}${route}`, provider: { "@id": `${site}/#organization` }, areaServed: "UA" });
  }
  if (faqs.length) graph.push({ "@type": "FAQPage", mainEntity: faqs.map(([q, a]) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })) });
  return JSON.stringify({ "@context": "https://schema.org", "@graph": graph });
};

const documentShell = ({ route, title, description, active, body, schema, article = false }) => `<!doctype html>
<html lang="uk"><head>${googleTag}<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index, follow, max-image-preview:large"><title>${escapeHtml(title)}</title><meta name="description" content="${escapeHtml(description)}"><link rel="canonical" href="${site}${route}"><meta name="theme-color" content="#05070A"><meta property="og:locale" content="uk_UA"><meta property="og:site_name" content="MAX SITE"><meta property="og:type" content="${article ? "article" : "website"}"><meta property="og:title" content="${escapeHtml(title)}"><meta property="og:description" content="${escapeHtml(description)}"><meta property="og:url" content="${site}${route}"><meta property="og:image" content="${site}/assets/og-max-site.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escapeHtml(title)}"><meta name="twitter:description" content="${escapeHtml(description)}"><meta name="twitter:image" content="${site}/assets/og-max-site.png"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css?v=20260820-seo-master"><script type="application/ld+json">${schema}</script></head><body>${header(active)}${body}${footer}</body></html>`;

const writePage = (route, html) => {
  const directory = path.join(root, route.replace(/^\//, ""));
  fs.mkdirSync(directory, { recursive: true });
  fs.writeFileSync(path.join(directory, "index.html"), html);
};

