  const body = `<main class="section seo-page"><nav class="breadcrumbs" aria-label="Хлібні крихти"><span><a href="/">Головна</a></span><span><a href="/nishi/">Ніші</a></span><span>${escapeHtml(h1)}</span></nav><section class="seo-hero reveal"><div><span class="eyebrow">Рішення для ніші</span><h1>${escapeHtml(h1)}</h1><p>Проєктуємо сайт під реальний шлях клієнта: від конкретної потреби до зрозумілого звернення.</p><div class="hero-buttons"><a class="btn" href="#lead">Отримати структуру</a><a class="btn btn-ghost" href="/portfolio/">Переглянути кейси</a></div></div><aside class="seo-hero-card"><strong>Не шаблон ніші</strong><p>Контент, сторінки й докази визначаються бізнес-моделлю, а не підстановкою назви міста.</p></aside></section><div class="seo-content"><section class="seo-band"><h2>Що важливо для ${escapeHtml(owner)}</h2><p>Сайт має пояснити ${escapeHtml(structure)}. Ми розділяємо інформаційні й комерційні наміри, прибираємо зайві кроки та не вигадуємо офіси, відгуки, ліцензії або показники, яких бізнес не підтвердив.</p></section><section class="seo-band"><h2>Рекомендована структура</h2><div class="seo-columns">${clusters.map((name) => `<article class="seo-mini-card"><h3>${escapeHtml(name)}</h3><p>Окремий блок або сторінка з відповіддю на конкретну потребу користувача.</p></article>`).join("")}</div><p>Фінальна карта залежить від семантики, географії, конкурентів, наявних матеріалів і пріоритету послуг. Слабкі масові сторінки не публікуємо для індексації.</p></section><section class="seo-band"><h2>Що входить у запуск</h2><ul class="seo-list-clean"><li>Аналіз задачі й пошукових намірів</li><li>Карта URL без канібалізації</li><li>Прототип ключових сторінок</li><li>Адаптивний дизайн</li><li>Форми, телефон і месенджери</li><li>GA4, Search Console і технічний QA</li></ul></section><section class="seo-links"><h2>Наступний крок</h2><div class="link-grid"><a href="/stvorennya-saytiv/">Створення сайтів</a><a href="/seo-first/">Методологія SEO-FIRST™</a><a href="/google-ads/">Google Ads</a><a href="/qa-checklist/">Контроль запуску</a></div></section>${faqMarkup(faqs)}${lead(`Потрібен ${h1.toLowerCase()}?`)}</div></main>`;
