for (const [file, marker, link] of [
  ["pro-nas/index.html", "seo-master-founder-link", '<p id="seo-master-founder-link"><a class="text-link" href="/zasnovnyk/">Докладніше про відповідального за проєкт</a> · <a class="text-link" href="/seo-first/">Методологія SEO-FIRST™</a></p>'],
  ["portfolio/index.html", "seo-master-case-links", '<section class="seo-links" id="seo-master-case-links"><h2>Докладні кейси</h2><div class="link-grid"><a href="/portfolio/formula-chystoty/">Кейс «Формула Чистоти»</a><a href="/portfolio/fo-dez/">Кейс FO-DEZ</a></div></section>'],
]) {
  const full = path.join(root, file);
  let content = fs.readFileSync(full, "utf8");
  if (!content.includes(marker)) {
    if (file === "portfolio/index.html") {
      content = content.replace('<section class="portfolio-links seo-links reveal">', `${link}<section class="portfolio-links seo-links reveal">`);
    } else {
      content = content.replace(/<section class="seo-lead[^>]*id="lead"[^>]*>/, `${link}$&`);
    }
    fs.writeFileSync(full, content);
  }
}

for (const file of fs.readdirSync(path.join(root, "blog"))) {
  const articleFile = path.join(root, "blog", file, "index.html");
  if (!fs.existsSync(articleFile)) continue;
  let content = fs.readFileSync(articleFile, "utf8");
  content = content.replaceAll('"author":{"@id":"https://maxsite.com.ua/#organization"}', '"author":{"@id":"https://maxsite.com.ua/zasnovnyk/#person"}');
  if (content.includes('class="article-body') && !content.includes('class="article-author"')) {
    content = content.replace(/<\/article>/, '<p class="article-author">Матеріал підготовлено засновником MAX SITE. <a href="/zasnovnyk/">Про автора та принципи роботи</a>.</p></article>');
  }
  fs.writeFileSync(articleFile, content);
}

const collectHtml = (directory) => {
  const files = [];
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    if ([".git", "release", "docs", "tools"].includes(entry.name)) continue;
    const full = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...collectHtml(full));
    else if (entry.name === "index.html") files.push(full);
  }
  return files;
};

for (const file of collectHtml(root)) {
  const content = fs.readFileSync(file, "utf8");
  if (content.includes("assets/og-max-site.png")) {
    fs.writeFileSync(file, content.replaceAll("assets/og-max-site.png", "assets/og-max-site.webp"));
  }
}

const sitemapRows = [];
for (const file of collectHtml(root)) {
  const html = fs.readFileSync(file, "utf8");
  if (/name="robots"[^>]*content="[^"]*noindex/i.test(html)) continue;
  const canonical = html.match(/<link rel="canonical" href="([^"]+)"/i)?.[1];
  if (!canonical || !canonical.startsWith(`${site}/`)) continue;
  const relative = path.relative(root, file).replaceAll(path.sep, "/");
  const route = relative === "index.html" ? "/" : `/${relative.replace(/index\.html$/, "")}`;
  if (canonical !== `${site}${route}`) continue;
  const priority = route === "/" ? "1.0" : route.startsWith("/blog/") ? "0.7" : route.startsWith("/portfolio/") ? "0.8" : "0.8";
  sitemapRows.push({ canonical, priority });
}
sitemapRows.sort((a, b) => a.canonical.localeCompare(b.canonical, "uk"));
fs.writeFileSync(path.join(root, "sitemap.xml"), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapRows.map(({ canonical, priority }) => `  <url><loc>${canonical}</loc><lastmod>${updated}</lastmod><priority>${priority}</priority></url>`).join("\n")}\n</urlset>\n`);

